 for j,d in enumerate(defs):
  if d[0]=='c': B[:,j]=1
  elif d[0]=='l': B[:,j]=X[:,d[1]]
  elif d[0]=='h': B[:,j]=np.maximum(X[:,d[1]]-d[2],0)
  elif d[0]=='p': B[:,j]=X[:,d[1]]*X[:,d[2]]
  elif d[0]=='q': B[:,j]=np.maximum(X[:,d[1]]-d[3],0)*np.maximum(X[:,d[2]]-d[4],0)
 return B
def fit(B,y):
 scale=np.sqrt(np.mean(B**2,axis=0)); scale=np.maximum(scale,1e-8)
 Z=B/scale
 b=np.linalg.solve(Z.T@Z+np.eye(B.shape[1])*1e-5,Z.T@y)/scale
 return b
